  "file_path": "/workspace/work/final_report.py",
  "content": """"One-shot development report: degeneracy diagnostics + aggregation comparison."""
import json
import sys
from collections import defaultdict

import numpy as np

sys.path.insert(0, "/workspace/work")
sys.path.insert(0, "/workspace/suite")
sys.path.insert(0, "/workspace")
from research_sdk import Client  # noqa: E402
import bench  # noqa: E402
import decide  # noqa: E402
from analyze import evaluate  # noqa: E402

ITEMS = {i["id"]: i for i in bench.build_all()}
c = Client()


def grab():
    out = {}
    for path in ("/workspace/work/jobs_v1.json", "/workspace/work/jobs_probe.json"):
        try:
            jobs = json.load(open(path))
        except Exception:
            continue
        for m, j in jobs.items():
            try:
                r = c.status(j)
            except Exception as e:
                print("status err", m, repr(e)[:120])
                continue
            if r.get("status") != "ok":
                print("job not ok:", m, r.get("status"))
                continue
            rows = (r.get("result") or {}).get("items", [])
            out[m] = {it["id"]: (it.get("score") if it.get("execution_status") == "completed" else None)
                      for it in rows}
            comp = sum(1 for v in out[m].values() if v is not None)
            print("%-16s rows=%3d completed=%3d mean=%.3f" %
                  (m, len(rows), comp,
                   float(np.mean([v for v in out[m].values() if v is not None])) if comp else float("nan")))
    json.dump(out, open("/workspace/work/scores.json", "w"), indent=1)
    return out


def family_table(scores):
    print("\n--- per-family means (None = item not completed) ---")
    fams = defaultdict(list)
    for i, it in ITEMS.items():
        fams[(it["domain"], it["family"])].append(i)
    models = list(scores)
    hdr = "%-28s %4s " % ("domain/family", "n") + " ".join("%14s" % m for m in models)
    print(hdr)
    for key in sorted(fams):
        ids = fams[key]
        cells = []
        for m in models:
            vals = [scores[m][i] for i in ids if scores[m].get(i) is not None]
            cells.append("%6.3f(%2d)" % (float(np.mean(vals)), len(vals)) if vals else "     -    ")
        print("%-28s %4d " % ("/".join(key), len(ids)) + " ".join("%14s" % c for c in cells))


def main():
    scores = grab()
    if not scores:
        print("no completed jobs yet")
        return
    family_table(scores)
    usable = {m: s for m, s in scores.items()
              if any(v is not None for v in s.values())}
    if len(usable) >= 3:
        decide.main(usable)
    else:
        print("\nfewer than 3 models with results: correlations not computable")
        for m, s in usable.items():
            for d in ("coding", "co-work", "reasoning"):
                ids = [i for i in s if ITEMS[i]["domain"] == d and s[i] is not None]
                if ids:
                    print("  %-16s %-9s n=%2d mean=%.4f uniq=%d" %
                          (m, d, len(ids), float(np.mean([s[i] for i in ids])),
                           len({round(s[i], 6) for i in ids})))


if __name__ == "__main__":
    main()
